using AcxiomCRM.Data;using AcxiomCRM.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;[Authorize(Roles="Admin,Manager")]public class AuditController:Controller{private readonly ApplicationDbContext _db;public AuditController(ApplicationDbContext db){_db=db;}public async Task<IActionResult>Index(string? action,string? entity){var q=_db.AuditLogs.AsQueryable();if(!string.IsNullOrWhiteSpace(action))q=q.Where(x=>x.Action==action);if(!string.IsNullOrWhiteSpace(entity))q=q.Where(x=>x.EntityName==entity);return View(await q.OrderByDescending(x=>x.CreatedDate).Take(500).ToListAsync());}}
